### Step 1: Set up the Python Script

First, create a Python script that will write data to a TCP server.

```python
import socket

# Define the address of the listening server
server_address = ('localhost', 6789)

# Create a socket object
sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

# Bind the socket to the address and port
sock.bind(server_address)
print('Server started. Listening at', sock.getsockname())

# Listen for incoming connections
sock.listen(5)
print('Waiting for a connection')

# Accept an incoming connection
connection, client_address = sock.accept()

try:
    print(f'Connection from {client_address}')

    # Receive data from the client
    while True:
        data = connection.recv(1024)
        if data:
            print(f'Received "{data.decode()}"')
            response = input("Enter your message (or 'quit' to close): ")
            if response.lower() == 'quit':
                break
            else:
                connection.sendall(response.encode())
except Exception as e:
    print(f"Error occurred: {e}")
finally:
    # Close the connection
    connection.close()
```

